# ================================================================================

TARGETS_shipping_discount = ["invalid", "free_express_shipping", "standard_discount", "small_discount", "no_discount"]

def fitness_shipping_discount(chromosome, target):
    order_total, distance, is_member = chromosome
    K = 1.0 # Small constant for normalization

    # Helper functions to calculate branch distance for a condition
    # Returns 0.0 if the condition is met, a positive value otherwise.
    # The value indicates how "far" the current input is from satisfying the condition.

    def _bd_ge(value, threshold): # Distance to make value >= threshold
        if value >= threshold:
            return 0.0
        return (threshold - value) + K

    def _bd_lt(value, threshold): # Distance to make value < threshold
        if value < threshold:
            return 0.0
        return (value - threshold) + K

    def _bd_le(value, threshold): # Distance to make value <= threshold
        if value <= threshold:
            return 0.0
        return (value - threshold) + K

    def _bd_is_true(value_bool): # Distance to make boolean value True
        if value_bool:
            return 0.0
        return K

    def _bd_is_false(value_bool): # Distance to make boolean value False
        if not value_bool:
            return 0.0
        return K

    # Initialize accumulated distance for negating previous conditions
    # This represents how "far" we are from reaching the current target's branch
    # by successfully avoiding all preceding branches.
    accumulated_negation_dist = 0.0

    # Target: "invalid" (order_total < 0 or distance < 0)
