    bd_dist_le_50 = _bd_le(distance, 50.0)
    bd_is_member = _bd_is_true(is_member)
    dist_to_satisfy_free_express = bd_ot_ge_200 + bd_dist_le_50 + bd_is_member

    if target == "free_express_shipping":
        return accumulated_negation_dist + dist_to_satisfy_free_express

    # If target is not "free_express_shipping", we must ensure
    # (order_total < 200 or distance > 50 or not is_member)
    # The distance to achieve this is the minimum of distances to make each part true.
