# Original function: sign_type
# Fitness function: fitness_sign_type
# LLM targets: ['positive', 'negative', 'zero']
# Notes: The fitness function calculates the branch distance for the 'positive', 'negative', and 'zero' outcomes based on the value of 'x'. For 'positive' (x > 0), it measures how far x is from being greater than 0. For 'negative' (x < 0), it measures how far x is from being less than 0. For 'zero' (x == 0), it measures the absolute difference from 0.
# ================================================================================

def fitness_sign_type(chromosome, target):
    x = chromosome[0]

    if target == "positive":
        # Target: x > 0
        # If x is already > 0, fitness is 0.
        # Otherwise, we want to make x positive, so we calculate distance from 0.
        return max(0, 1 - x)
    elif target == "negative":
        # Target: x < 0
        # If x is already < 0, fitness is 0.
        # Otherwise, we want to make x negative, so we calculate distance from 0.
        return max(0, x + 1)
    elif target == "zero":
        # Target: x == 0
        # If x is 0, fitness is 0.
        # Otherwise, the distance is the absolute value of x.
        return abs(x)
    else:
        raise ValueError(f"Unknown target: {target}")

# ================================================================================
# Original function: string_category
# Fitness function: fitness_string_category
# LLM targets: ['empty', 'long_palindrome', 'short_palindrome', 'long_non_palindrome', 'other']
# Notes: The fitness function uses branch distance to guide the search for inputs that cover specific return paths. It calculates the sum of distances for each condition that must be met (or negated) to reach the target. A small constant 'k' is added for strict inequalities to ensure a positive distance when a condition is not strictly met.
# ================================================================================

TARGETS_string_category = [
    "empty",
    "long_palindrome",
    "short_palindrome",
    "long_non_palindrome",
    "other"
]

def fitness_string_category(chromosome, target):
    s = chromosome[0]
    _len_s = len(s)
    is_palindrome = (s == s[::-1])

    k = 1.0

    def dist_true(condition_val):
        return 0.0 if condition_val else k

    def dist_false(condition_val):
        return 0.0 if not condition_val else k

    if target == "empty":
        return abs(_len_s - 0)

    elif target == "long_palindrome":
        fitness = 0.0
        fitness += dist_false(_len_s == 0)
        fitness += dist_true(is_palindrome)
        fitness += max(0.0, 3.0 - _len_s + k)
        return fitness

    elif target == "short_palindrome":
        fitness = 0.0
        fitness += dist_false(_len_s == 0)
        fitness += dist_true(is_palindrome)
        fitness += max(0.0, _len_s - 3.0)
        return fitness

    elif target == "long_non_palindrome":
        fitness = 0.0
        fitness += dist_false(_len_s == 0)
        fitness += dist_false(is_palindrome)
        fitness += max(0.0, 5.0 - _len_s + k)
        return fitness

    elif target == "other":
        fitness = 0.0
        fitness += dist_false(_len_s == 0)
        fitness += dist_false(is_palindrome)
        fitness += max(0.0, _len_s - 5.0)
        return fitness

    else:
        raise ValueError("Unknown target: " + target)

# ================================================================================
# Original function: transaction_pattern
# Fitness function: fitness_transaction_pattern
# LLM targets: ['empty', 'contains_zero', 'many_large_deposits', 'many_large_withdrawals', 'mixed_transactions', 'simple_pattern']
# Notes: The fitness function simulates the control flow of the original 'transaction_pattern' function. For each target, it returns 0 if the input chromosome satisfies the conditions to reach that target. If a different branch is taken, a large penalty (1000) is added to ensure it does not return 0 for a non-target path. Otherwise, it calculates branch distances for the conditions leading to the specific target.
# ================================================================================

def fitness_transaction_pattern(chromosome, target):
    amounts = chromosome[0]

    def br_dist_eq(left, right):
        return abs(left - right)

    def br_dist_ne(left, right):
        return 0 if left != right else 1

    def br_dist_gt(left, right):
        return max(0, right - left + 1)

    def br_dist_ge(left, right):
        return max(0, right - left)

    def br_dist_lt(left, right):
        return max(0, left - right + 1)

    def br_dist_le(left, right):
        return max(0, left - right)

    def br_dist_any_eq_zero(lst):
        if not lst:
            return 1
        if 0 in lst:
            return 0
        return min(abs(x) for x in lst)

    def check_any_eq_zero(lst):
        if not lst:
            return False
        return 0 in lst

    # --- Simulate original function's control flow --- 
    
    # Branch 1: len(amounts) == 0
    cond1_len_eq_0 = (len(amounts) == 0)
    if target == "empty":
        return br_dist_eq(len(amounts), 0)
    elif cond1_len_eq_0:
        return br_dist_eq(len(amounts), 0) + 1000

    # Branch 2: any(x == 0 for x in amounts)
    cond2_any_eq_0 = check_any_eq_zero(amounts)
    if target == "contains_zero":
        return br_dist_any_eq_zero(amounts)
    elif cond2_any_eq_0:
        return br_dist_any_eq_zero(amounts) + 1000

    # Calculate common values for remaining branches
    positives = sum(1 for x in amounts if x > 0)
    negatives = sum(1 for x in amounts if x < 0)
    total = sum(amounts)

    # Branch 3: positives >= 3 and negatives == 0 and total > 100
    cond3_mld = (positives >= 3 and negatives == 0 and total > 100)
    if target == "many_large_deposits":
        return (br_dist_ge(positives, 3) +
                br_dist_eq(negatives, 0) +
                br_dist_gt(total, 100))
    elif cond3_mld:
        return (br_dist_ge(positives, 3) +
                br_dist_eq(negatives, 0) +
                br_dist_gt(total, 100)) + 1000

    # Branch 4: negatives >= 2 and total < -50
    cond4_mlw = (negatives >= 2 and total < -50)
    if target == "many_large_withdrawals":
        return (br_dist_ge(negatives, 2) +
                br_dist_lt(total, -50))
    elif cond4_mlw:
        return (br_dist_ge(negatives, 2) +
                br_dist_lt(total, -50)) + 1000

    # Branch 5: positives > 0 and negatives > 0
    cond5_mixed = (positives > 0 and negatives > 0)
    if target == "mixed_transactions":
        return (br_dist_gt(positives, 0) +
                br_dist_gt(negatives, 0))
    elif cond5_mixed:
        return (br_dist_gt(positives, 0) +
                br_dist_gt(negatives, 0)) + 1000

    # Branch 6: "simple_pattern" (default return)
    if target == "simple_pattern":
        return 0
    else:
        return 1000

    raise ValueError("Unknown target: " + target)

# ================================================================================
# Original function: triangle_type
# Fitness function: fitness_triangle_type
# LLM targets: ['invalid_side', 'not_triangle', 'equilateral', 'isosceles', 'scalene']
# Notes: The fitness function uses branch distance. For `if/elif/else` structures, it accumulates a penalty of 1.0 if a preceding `if` or `elif` condition that would lead to a different target is met, otherwise 0.0. Conditions are combined with sum for AND and minimum for OR. `max(0.0, ...)` ensures non-negative fitness values.
# ================================================================================

def fitness_triangle_type(chromosome, target):
    a, b, c = chromosome

    # Helper functions for branch distance (return 0 if condition met, positive otherwise)
    # dist_true_le(X, Y): Distance to make X <= Y true. Returns 0 if X <= Y, positive otherwise.
    def dist_true_le(X, Y): return max(0.0, float(X - Y + 1))

    # dist_true_gt(X, Y): Distance to make X > Y true. Returns 0 if X > Y, positive otherwise.
    def dist_true_gt(X, Y): return max(0.0, float(Y - X + 1))

    # dist_true_eq(X, Y): Distance to make X == Y true. Returns 0 if X == Y, positive otherwise.
    def dist_true_eq(X, Y): return abs(float(X - Y))

    # Distances for individual conditions to be TRUE
    d_a_le_0 = dist_true_le(a, 0)
    d_b_le_0 = dist_true_le(b, 0)
    d_c_le_0 = dist_true_le(c, 0)

    d_ab_le_c = dist_true_le(a + b, c)
    d_ac_le_b = dist_true_le(a + c, b)
    d_bc_le_a = dist_true_le(b + c, a)

    d_a_eq_b = dist_true_eq(a, b)
    d_b_eq_c = dist_true_eq(b, c)
    d_a_eq_c = dist_true_eq(a, c)

    # Fitness for "invalid_side" target
    if target == "invalid_side":
        # Condition: a <= 0 or b <= 0 or c <= 0 (OR condition: take minimum distance)
        return min(d_a_le_0, d_b_le_0, d_c_le_0)

    # Cost to bypass the "invalid_side" branch (i.e., make a > 0 AND b > 0 AND c > 0)
    # Sum of distances for each sub-condition to be true (AND condition)
    cost_not_invalid_side = dist_true_gt(a, 0) + dist_true_gt(b, 0) + dist_true_gt(c, 0)

    # Fitness for "not_triangle" target
    if target == "not_triangle":
        # Condition: (a + b <= c or a + c <= b or b + c <= a) (OR condition: take minimum distance)
        d_not_triangle_cond = min(d_ab_le_c, d_ac_le_b, d_bc_le_a)
        return cost_not_invalid_side + d_not_triangle_cond

    # Cost to bypass the "not_triangle" branch (i.e., make a+b > c AND a+c > b AND b+c > a)
    cost_not_not_triangle = dist_true_gt(a + b, c) + dist_true_gt(a + c, b) + dist_true_gt(b + c, a)

    # Fitness for "equilateral" target
    if target == "equilateral":
        # Condition: (a == b and b == c) (AND condition: sum distances)
        d_equilateral_cond = d_a_eq_b + d_b_eq_c
        return cost_not_invalid_side + cost_not_not_triangle + d_equilateral_cond

    # Cost to bypass the "equilateral" branch (i.e., make NOT (a == b AND b == c))
    # If (a == b and b == c) is true (d_a_eq_b + d_b_eq_c == 0.0), add a penalty of 1.0
    # Otherwise, 0.0 penalty.
    cost_not_equilateral = 1.0 if (d_a_eq_b + d_b_eq_c == 0.0) else 0.0

    # Fitness for "isosceles" target
    if target == "isosceles":
        # Condition: (a == b or a == c or b == c) (OR condition: take minimum distance)
        d_isosceles_cond = min(d_a_eq_b, d_a_eq_c, d_b_eq_c)
        return cost_not_invalid_side + cost_not_not_triangle + cost_not_equilateral + d_isosceles_cond

    # Cost to bypass the "isosceles" branch (i.e., make NOT (a == b OR a == c OR b == c))
    # If (a == b or a == c or b == c) is true (min(...) == 0.0), add a penalty of 1.0
    # Otherwise, 0.0 penalty.
    cost_not_isosceles = 1.0 if (min(d_a_eq_b, d_a_eq_c, d_b_eq_c) == 0.0) else 0.0

    # Fitness for "scalene" target
    if target == "scalene":
        # This is the 'else' branch, requiring all preceding conditions to be false.
        return cost_not_invalid_side + cost_not_not_triangle + cost_not_equilateral + cost_not_isosceles

    raise ValueError("Unknown target: " + target)

# ================================================================================
# Original function: username_category
# Fitness function: fitness_username_category
# LLM targets: ['empty', 'too_short', 'starts_with_digit', 'strong_username', 'medium_username', 'weak_username']
# Notes: The fitness function `fitness_username_category` calculates a branch distance for each target. It combines an 'approach level' (sum of distances to satisfy conditions to reach a target branch) and a 'branch distance' (distance to satisfy the condition of the target branch itself). Helper functions `gd_true`, `gd_false`, `gd_eq`, `gd_lt`, and `gd_ge` are used to calculate distances for boolean and relational conditions, ensuring all distances are non-negative. A constant K=1 is used for normalization where a condition is not met.
# ================================================================================

TARGETS_username_category = [
    "empty",
    "too_short",
    "starts_with_digit",
    "strong_username",
    "medium_username",
    "weak_username"
]

def fitness_username_category(chromosome, target):
    username = chromosome[0]
    K = 1 # Normalization constant for boolean distances

    # Helper for generalized branch distance functions
    # Returns 0 if condition is met, positive otherwise.
    def gd_true(condition):
        return 0 if condition else K

    def gd_false(condition):
        return 0 if not condition else K

    def gd_eq(a, b): # Distance to make a == b true
        return abs(a - b)

    def gd_lt(a, b): # Distance to make a < b true
        # If a < b is true, a - b is negative. max(0, negative + K) is 0 if K is positive and sufficiently small.
        # If a >= b, a - b is positive or zero. max(0, positive + K) is positive.
        return max(0, a - b + K)

    def gd_ge(a, b): # Distance to make a >= b true
        # If a >= b is true, b - a is negative or zero. max(0, negative + K) is 0 if K is positive and sufficiently small.
        # If a < b, b - a is positive. max(0, positive + K) is positive.
        return max(0, b - a + K)

    len_username = len(username)

    has_digit = any(ch.isdigit() for ch in username)
    has_upper = any(ch.isupper() for ch in username)
    has_special = any(not ch.isalnum() for ch in username)
    
    first_char_is_digit = False
    if len_username > 0:
        first_char_is_digit = username[0].isdigit()

    if target == "empty":
        # Target: if len(username) == 0: return "empty"
        return gd_eq(len_username, 0)

    if target == "too_short":
        # Path: len(username) != 0 AND len(username) < 5
        approach_level = 0
        branch_distance = 0
        
        # 1. Bypass 'len(username) == 0' (i.e., len(username) != 0 must be true)
        approach_level += gd_false(len_username == 0)
        
        # 2. Target 'len(username) < 5'
        branch_distance = gd_lt(len_username, 5)
        return approach_level + branch_distance

    if target == "starts_with_digit":
        # Path: len(username) != 0 AND len(username) >= 5 AND username[0].isdigit()
        approach_level = 0
        branch_distance = 0
        
        # 1. Bypass 'len(username) == 0'
        approach_level += gd_false(len_username == 0)
        # 2. Bypass 'len(username) < 5' (i.e., len(username) >= 5 must be true)
        approach_level += gd_false(len_username < 5)
        
        # 3. Target 'username[0].isdigit()'
        branch_distance = gd_true(first_char_is_digit)
        return approach_level + branch_distance

    if target == "strong_username":
        # Path: len(username) != 0 AND len(username) >= 5 AND !username[0].isdigit() AND
        #       (len(username) >= 10 AND has_digit AND has_upper AND has_special)
        approach_level = 0
        branch_distance = 0
        
        # 1. Bypass 'len(username) == 0'
        approach_level += gd_false(len_username == 0)
        # 2. Bypass 'len(username) < 5'
        approach_level += gd_false(len_username < 5)
        # 3. Bypass 'username[0].isdigit()' (i.e., username[0].isdigit() must be false)
        approach_level += gd_false(first_char_is_digit)
        
        # 4. Target 'len(username) >= 10 AND has_digit AND has_upper AND has_special'
        # For an AND condition, sum the individual distances.
        branch_distance += gd_ge(len_username, 10)
        branch_distance += gd_true(has_digit)
        branch_distance += gd_true(has_upper)
        branch_distance += gd_true(has_special)
        return approach_level + branch_distance

    if target == "medium_username":
        # Path: len(username) != 0 AND len(username) >= 5 AND !username[0].isdigit() AND
        #       !(len(username) >= 10 AND has_digit AND has_upper AND has_special) AND
        #       (has_digit AND has_upper)
        approach_level = 0
        branch_distance = 0
        
        # 1. Bypass 'len(username) == 0'
        approach_level += gd_false(len_username == 0)
        # 2. Bypass 'len(username) < 5'
        approach_level += gd_false(len_username < 5)
        # 3. Bypass 'username[0].isdigit()'
        approach_level += gd_false(first_char_is_digit)
        
        # 4. Bypass 'strong_username' condition
        strong_cond = (len_username >= 10 and has_digit and has_upper and has_special)
        approach_level += gd_false(strong_cond) # Distance to make this composite condition false
        
        # 5. Target '(has_digit AND has_upper)'
        branch_distance += gd_true(has_digit)
        branch_distance += gd_true(has_upper)
        return approach_level + branch_distance

    if target == "weak_username":
        # Path: len(username) != 0 AND len(username) >= 5 AND !username[0].isdigit() AND
        #       !(len(username) >= 10 AND has_digit AND has_upper AND has_special) AND
        #       !(has_digit AND has_upper)
        approach_level = 0
        branch_distance = 0 # Default return, no specific branch to satisfy here
        
        # 1. Bypass 'len(username) == 0'
        approach_level += gd_false(len_username == 0)
        # 2. Bypass 'len(username) < 5'
        approach_level += gd_false(len_username < 5)
        # 3. Bypass 'username[0].isdigit()'
        approach_level += gd_false(first_char_is_digit)
        
        # 4. Bypass 'strong_username' condition
        strong_cond = (len_username >= 10 and has_digit and has_upper and has_special)
        approach_level += gd_false(strong_cond)
        
        # 5. Bypass 'medium_username' condition
        medium_cond = (has_digit and has_upper)
        approach_level += gd_false(medium_cond)
        
        return approach_level + branch_distance

    raise ValueError("Unknown target: " + target)

# ================================================================================
# Unified fitness interface
# ================================================================================

def evaluate_fitness(function_name, chromosome, target):
    if function_name == 'bmi_category':
        return fitness_bmi_category(chromosome, target)
    elif function_name == 'list_pattern':
        return fitness_list_pattern(chromosome, target)
    elif function_name == 'number_kind':
        return fitness_number_kind(chromosome, target)
    elif function_name == 'password_strength':
        return fitness_password_strength(chromosome, target)
    elif function_name == 'pin_pattern':
        return fitness_pin_pattern(chromosome, target)
    elif function_name == 'shipping_discount':
        return fitness_shipping_discount(chromosome, target)
    elif function_name == 'sign_type':
        return fitness_sign_type(chromosome, target)
    elif function_name == 'string_category':
        return fitness_string_category(chromosome, target)
    elif function_name == 'transaction_pattern':
        return fitness_transaction_pattern(chromosome, target)
    elif function_name == 'triangle_type':
        return fitness_triangle_type(chromosome, target)
    elif function_name == 'username_category':
        return fitness_username_category(chromosome, target)
    else:
        raise ValueError(f'Unknown function name: {function_name}')
